/* @lc app=leetcode id=3458 lang=kotlin */ class Solution { fun maxSubstringLength(s: String, k: Int): Boolean = s.length.let { n -> s.indices.associateBy { s[it] }.let { lastOf -> s.indices.reversed().associateBy { s[it] }.let { firstOf -> lastOf.keys.mapNotNull { c -> firstOf[c]!!.let { l -> generateSequence(lastOf[c]!!) { cur -> (l..cur).maxOf { lastOf[s[it]]!! }.takeIf { it > cur } }.last().let { r -> if ((l..r).all { firstOf[s[it]]!! >= l } && !(l == 0 && r == n - 1)) l to r else null } } }.sortedBy { it.second }.fold(-1 to 0) { (end, cnt), (l, r) -> if (l > end) r to cnt + 1 else end to cnt }.second >= k } } } }